import type { ColorKey, SqlScope } from '../../src/shared/theme/registry'

/**
 * Every color the workbench painted before themes existed, mapped to the key that now owns it. `over` is the surface a
 * translucent key is compared on; `change` marks a deliberate Varia Dark change (spec B16) and says why.
 */
export type LegacyTarget = ColorKey | `syntax:${SqlScope}`
export interface LegacyColor { source: string; line?: number; value: string; keys: LegacyTarget[]; over?: ColorKey; change?: string }

const css = (line: number, value: string, key: LegacyTarget | LegacyTarget[], extra: Partial<LegacyColor> = {}): LegacyColor =>
  ({ source: 'styles.css', line, value, keys: Array.isArray(key) ? key : [key], ...extra })
const aa = (before: string, after: string) => `AA: ${before} -> ${after}.`

